import"./chunk-7CGTOI24.js";var e={slug:"review-clair-obscur-expedition-33",title:"Review: Clair Obscur: Expedition 33 reinventa o RPG por turnos",dek:"O RPG da francesa Sandfall Interactive mistura turnos com reflexo, uma hist\xF3ria comovente e uma dire\xE7\xE3o de arte que parece pintura. Ainda \xE9 um dos jogos a jogar.",section:"games",kind:"review",tags:["RPG","PlayStation","Xbox","PC"],date:"2026-10-15",hero:{ref:"game:305152",pick:0,alt:"Personagens de Clair Obscur: Expedition 33 diante de uma paisagem pintada"},score:9.5,verdict:{summary:"Combate original, elenco memor\xE1vel e um mundo que parece sa\xEDdo de um quadro. Clair Obscur \xE9 a prova de que um est\xFAdio estreante pode disputar com os gigantes.",good:["Turnos com esquiva e aparo em tempo real","Roteiro maduro, com um elenco que voc\xEA leva com voc\xEA","Dire\xE7\xE3o de arte e trilha marcantes"],bad:["Mapa do mundo pouco intuitivo em alguns trechos","Picos de dificuldade em chefes opcionais"]},body:[{p:"Todo ano, a Pintora acorda e pinta um n\xFAmero em seu mon\xF3lito. Todas as pessoas com aquela idade desaparecem. \xC9 com essa premissa, cruel e po\xE9tica, que *Clair Obscur: Expedition 33* nos apresenta a cidade de Lumi\xE8re e a Expedi\xE7\xE3o 33, um grupo que parte para destruir a Pintora antes que ela pinte o pr\xF3ximo n\xFAmero."},{p:"Lan\xE7ado em 24 de abril de 2025 para PC, PlayStation 5 e Xbox Series X|S, o jogo \xE9 o primeiro da **Sandfall Interactive**, est\xFAdio franc\xEAs, com publica\xE7\xE3o da Kepler Interactive. Voltamos a ele agora porque continua sendo uma das melhores portas de entrada para o g\xEAnero."},{ficha:"game:305152"},{h2:"Turnos que pedem reflexo"},{p:"O combate \xE9 por turnos, mas n\xE3o \xE9 passivo. Na vez do inimigo, voc\xEA pode esquivar, aparar ou pular no tempo certo, e um aparo perfeito abre espa\xE7o para contra-ataques. Na sua vez, cada personagem tem uma mec\xE2nica pr\xF3pria, e o sistema de Pictos permite combinar efeitos passivos at\xE9 montar estrat\xE9gias bem espec\xEDficas."},{p:"O resultado \xE9 um RPG em que nenhuma luta \xE9 igual. Os chefes ensinam seus padr\xF5es, e a satisfa\xE7\xE3o de aparar uma sequ\xEAncia inteira de golpes \xE9 parecida com a de um bom jogo de a\xE7\xE3o."},{p:"O sistema tamb\xE9m \xE9 generoso com quem n\xE3o tem reflexos r\xE1pidos. D\xE1 para compensar com prepara\xE7\xE3o: equipamentos que aumentam a defesa, Pictos que recuperam vida ou pontos de a\xE7\xE3o, e personagens com pap\xE9is mais seguros na equipe. Quem gosta de montar personagem vai passar horas testando combina\xE7\xF5es; quem prefere a a\xE7\xE3o pura pode focar na esquiva e seguir em frente."},{h2:"Um mundo para explorar"},{p:"Fora das lutas, a expedi\xE7\xE3o atravessa um continente cheio de regi\xF5es distintas, cada uma com sua paleta, seus inimigos e seus segredos. H\xE1 chefes opcionais, \xE1reas escondidas e personagens secund\xE1rios com hist\xF3rias pr\xF3prias, o que d\xE1 ao jogo um ritmo de RPG cl\xE1ssico: avan\xE7ar na trama principal, desviar para explorar, voltar mais forte."},{p:"A explora\xE7\xE3o n\xE3o \xE9 t\xE3o livre quanto a de um mundo aberto moderno, mas o desenho dos cen\xE1rios compensa. Muitos caminhos se revelam s\xF3 depois de liberar novas formas de travessia, e o jogo recompensa a curiosidade com equipamentos e Pictos raros."},{img:"game:305152",pick:4,caption:"A est\xE9tica da Belle \xC9poque francesa d\xE1 identidade ao mundo do jogo. Imagem de divulga\xE7\xE3o."},{h2:"Gente de verdade"},{p:"Gustave, Maelle, Lune e Sciel s\xE3o personagens com d\xFAvidas, luto e humor. O roteiro trata a morte anunciada com seriedade, sem cair no melodrama f\xE1cil, e reserva viradas que mudam a forma como voc\xEA olha para tudo o que veio antes. N\xE3o vamos contar nada: chegue sem spoilers."},{quote:"Clair Obscur faz uma coisa rara: transforma um sistema de combate em linguagem emocional. Cada aparo parece uma pequena recusa ao fim."},{h2:"Pintura em movimento"},{p:"A dire\xE7\xE3o de arte \xE9 o primeiro impacto. Paisagens que parecem pinceladas, criaturas surreais e uma paleta que muda conforme a expedi\xE7\xE3o avan\xE7a. A trilha sonora acompanha esse cuidado, alternando entre o \xEDntimo e o grandioso. Os pontos fracos aparecem no mapa do mundo, \xE0s vezes confuso, e em alguns chefes opcionais que pedem mais repeti\xE7\xE3o do que o necess\xE1rio."},{h2:"Veredito"},{p:"Para quem chega agora, a recomenda\xE7\xE3o \xE9 jogar sem pressa e sem guias. O impacto da hist\xF3ria depende de n\xE3o saber o que vem a seguir, e as primeiras horas j\xE1 mostram se o combate vai te conquistar."},{p:"Se voc\xEA abandonou os RPGs por turnos por ach\xE1-los lentos, *Clair Obscur* \xE9 o convite para voltar. Se nunca saiu do g\xEAnero, \xE9 um lembrete de quanto ele ainda pode se reinventar. Nota 9,5."},{p:"Gosta de jogos que contam muito com pouco? Leia tamb\xE9m a nossa [review de Hollow Knight: Silksong](/artigo/review-hollow-knight-silksong)."}]};var o={source:"TMDB + IGDB",updatedAt:"2026-11-10",calendar:[],games:{305152:{id:305152,name:"Clair Obscur: Expedition 33",type:"Jogo principal",cover:"co9gam",shots:["scsoe2","scsoec","scsoe7","scsoee","scsoef","scsoe8"],arts:["ar3nmf","ar3lza","ar4yfy","ar3nmg"],genres:["RPG","Estrat\xE9gia por turnos","Aventura","Indie"],modes:["Single player"],devs:["Sandfall Interactive"],pubs:["Kepler Interactive"],released:"2025-04-24",releases:{"Xbox Series X|S":"2025-04-24",PC:"2025-04-24",PS5:"2025-04-24"},classInd:"18"}},movies:{},tv:{}};export{o as media,e as post};
